// Type-safe accessor for the trimmed world-countries dataset.
//
// src/data/countries-slim.json is generated by scripts/slim-countries.mjs from
// the world-countries package (https://github.com/mledoze/countries), which is
// licensed under the Open Database License (ODbL) v1.0:
// https://opendatacommons.org/licenses/odbl/1.0/
//
// The generated file carries a comment header with that attribution, so it is
// imported as raw text and parsed here after stripping the comment block.
// (Vite's built-in JSON handling rejects commented JSON, hence the ?raw import.)
import countriesSlimRaw from './countries-slim.json?raw'

export type SlimCountry = {
  name: {
    common: string
    official: string
  }
  altSpellings: string[]
  cca3: string
  ccn3: string
  latlng: [number, number]
  area: number
  region: string
  subregion: string
  borders: string[]
  capital: string[]
  unMember: boolean
}

const json = countriesSlimRaw.replace(/^(?:\s*\/\/[^\n]*\n)+/, '')

export const worldCountries = JSON.parse(json) as SlimCountry[]
